// ---------------- scenario recipes ----------------
export const RECIPES = [
  { id: 'r-squash', cat: 'recipe', title: 'Squash the last N commits', summary: 'Combine several commits into one.',
    fields: [f('n', 'Number of commits', 'int', { req: true, def: '3', min: 2 }), sel('how', 'Method', [['soft', 'reset --soft + new commit (simple)'], ['rebase', 'Interactive rebase']]), f('message', 'New message', 'text', { req: true, ex: 'Add login feature', show: is('how', 'soft') })],
    build(v, b) { if (v.how === 'soft') { b.git('reset', '--soft', Q(`HEAD~${v.n}`)).say('Moves the branch back but keeps all changes staged.'); b.git('commit', ...messageTokens(v.message)); } else { b.git('rebase', '-i', Q(`HEAD~${v.n}`)); b.comment('Keep the first "pick", change the others to "squash" (or "fixup"), save, then edit the message.'); }
      b.git('push', '--force-with-lease').say('Only if the commits were already pushed.'); b.danger('medium', REWRITE, 'git reflog, then git reset --hard <old tip>.'); } },
  { id: 'r-undo-pushed', cat: 'recipe', title: 'Undo a pushed commit safely', summary: 'Revert instead of rewriting history.',
    fields: [f('commit', 'Commit to undo', 'rev', { req: true, ex: 'a1b2c3d' }), chk('merge', 'It is a merge commit (-m 1)'), REMOTE, f('branch', 'Branch', 'ref', { req: true, def: 'main' })],
    build(v, b) { b.git('revert', v.merge && '-m', v.merge && '1', Q(v.commit)).say('Creates a new commit that cancels the change.'); b.git('push', Q(v.remote), Q(v.branch)); b.note('History stays intact, so teammates just pull normally.'); b.alt('git reset + force push rewrites shared history and should be avoided.'); } },
  { id: 'r-wrong-branch', cat: 'recipe', title: 'I committed on the wrong branch', summary: 'Move the commits to a new branch and clean the original.',
    fields: [f('new', 'New (correct) branch', 'ref', { req: true, ex: 'feature/x' }), f('orig', 'Branch you committed on', 'ref', { req: true, def: 'main' }), f('base', 'Where that branch should be', 'rev', { req: true, def: 'origin/main' })],
    build(v, b) { b.git('branch', Q(v.new)).say('Keep the commits: create the branch at the current tip.'); b.git('reset', '--hard', Q(v.base)).say(`Rewind ${v.orig || 'the original branch'} to where it should be.`); b.git('switch', Q(v.new));
      b.danger('high', 'reset --hard discards uncommitted changes. Commit or stash anything uncommitted first (it would stay on the original branch).', 'The commits are safe on the new branch; also git reflog.'); b.note('Run the first command before reset: the new branch name keeps your commits reachable.'); } },
  { id: 'r-sync-fork', cat: 'recipe', title: 'Sync a fork with upstream', summary: 'Bring the original repository\'s changes into your fork.',
    fields: [f('url', 'Upstream URL', 'url', { req: true, ex: 'https://github.com/original/repo.git' }), f('branch', 'Branch', 'ref', { req: true, def: 'main' }), sel('how', 'Integrate by', [['ffonly', 'Fast-forward only (clean mirror)'], ['rebase', 'Rebase my commits'], ['merge', 'Merge']])],
    build(v, b) { b.git('remote', 'add', 'upstream', Q(v.url)).say('Once only.'); b.git('fetch', 'upstream'); b.git('switch', Q(v.branch)); b.git(v.how === 'rebase' ? 'rebase' : 'merge', v.how === 'ffonly' && '--ff-only', Q(`upstream/${v.branch}`)); b.git('push', 'origin', Q(v.branch)); if (v.how === 'rebase') b.warn('After a rebase the push may need --force-with-lease.'); } },
  { id: 'r-split-commit', cat: 'recipe', title: 'Split a commit into two', summary: 'Rewrite one commit as several.',
    fields: [f('commit', 'Commit to split', 'rev', { req: true, ex: 'a1b2c3d' })],
    build(v, b) { b.git('rebase', '-i', Q(`${v.commit}^`)); b.comment('Change "pick" to "edit" for that commit, save and close.'); b.git('reset', 'HEAD^').say('Un-commit but keep the changes in the working tree.'); b.git('add', '-p').say('Stage the first part, interactively.'); b.git('commit', '-m', Q('First part')); b.git('add', '-p'); b.git('commit', '-m', Q('Second part')); b.git('rebase', '--continue'); b.danger('medium', REWRITE, 'git rebase --abort, or git reflog.'); } },
  { id: 'r-conflict', cat: 'recipe', title: 'Resolve a merge conflict', summary: 'Step by step for merge, rebase or cherry-pick.',
    fields: [sel('kind', 'Operation', [['merge', 'merge'], ['rebase', 'rebase'], ['cherry-pick', 'cherry-pick']]), f('file', 'Conflicted file', 'path', { req: true, ex: 'src/app.js' }), sel('pick', 'Resolve by', [['edit', 'Editing the markers by hand'], ['ours', 'Taking my version'], ['theirs', 'Taking their version']])],
    build(v, b) { b.git('status').say('Lists files with "both modified".'); b.git('diff', '--name-only', '--diff-filter=U').say('Only the unmerged files.');
      if (v.pick === 'edit') b.comment(`Open ${v.file} and resolve the <<<<<<< ======= >>>>>>> markers, then save.`); else { b.git('checkout', `--${v.pick}`, '--', Q(v.file)); b.note(v.kind === 'rebase' ? 'During a rebase "ours" is the branch you rebase ONTO and "theirs" is your own commit being replayed.' : '"ours" is your current branch, "theirs" the one being merged/picked.'); }
      b.git('add', '--', Q(v.file)); b.git(v.kind, '--continue'); b.alt(`git ${v.kind} --abort returns everything to how it was.`); b.alt('git mergetool opens a visual merge tool.'); } },
  { id: 'r-first-push', cat: 'recipe', title: 'Put a local project on a remote', summary: 'init, first commit, push.',
    fields: [f('url', 'Remote URL', 'url', { req: true, ex: 'git@github.com:me/project.git' }), f('branch', 'Branch', 'ref', { def: 'main', req: true })],
    build(v, b) { b.git('init', '-b', Q(v.branch)); b.git('add', '-A'); b.git('commit', '-m', Q('Initial commit')); b.git('remote', 'add', 'origin', Q(v.url)); b.git('push', '-u', 'origin', Q(v.branch)); b.note('Add a .gitignore before git add -A so secrets and build output stay out.'); } },
  { id: 'r-update-pr', cat: 'recipe', title: 'Update a feature branch before a pull request', summary: 'Rebase on the latest main and push.',
    fields: [f('base', 'Base branch', 'rev', { req: true, def: 'origin/main' })],
    build(v, b) { b.git('fetch', 'origin'); b.git('rebase', Q(v.base)); b.git('push', '--force-with-lease'); b.danger('medium', 'Rewrites the pushed feature branch.', 'git reflog and reset, or git rebase --abort during conflicts.'); b.alt('git merge origin/main avoids the force push.'); } },
  { id: 'r-rename-master', cat: 'recipe', title: 'Rename master to main', summary: 'Local and remote.',
    fields: [f('old', 'Old name', 'ref', { def: 'master', req: true }), f('new', 'New name', 'ref', { def: 'main', req: true })],
    build(v, b) { b.git('branch', '-m', Q(v.old), Q(v.new)); b.git('push', '-u', 'origin', Q(v.new)); b.comment('Change the default branch in the hosting service settings, then:'); b.git('push', 'origin', '--delete', Q(v.old)); b.note('Teammates run: git fetch, git branch -m old new, git branch -u origin/new new.'); } },
];

export const ALL_TASKS = [...TASKS, ...RECIPES];
